# Generic Classes 🧬

Classes can accept type parameters to manage arbitrary data:

```typescript
class Queue<T> {
  private data: T[] = [];

  enqueue(item: T): void {
    this.data.push(item);
  }

  dequeue(): T | undefined {
    return this.data.shift();
  }

  peek(): T | undefined {
    return this.data[0];
  }
}

const stringQueue = new Queue<string>();
stringQueue.enqueue("First");
stringQueue.enqueue("Second");
console.log("Dequeued:", stringQueue.dequeue()); // "First"
```

