# Real-World: Repository Pattern 🗄️

```typescript
interface Entity {
  id: string;
}

interface Repository<T extends Entity> {
  findById(id: string): T | undefined;
  save(item: T): void;
}

class InMemoryUserRepository implements Repository<{ id: string; name: string }> {
  private store = new Map<string, { id: string; name: string }>();

  findById(id: string) {
    return this.store.get(id);
  }

  save(user: { id: string; name: string }) {
    this.store.set(user.id, user);
  }
}

const userRepo = new InMemoryUserRepository();
userRepo.save({ id: "U1", name: "David" });
console.log("Found User:", userRepo.findById("U1"));
```

